WITH scored AS (SELECT *, AVG(amount) OVER w_ordered AS amount_avg_6_prior, SUM(amount) OVER (PARTITION BY order_id) AS order_id_sum_amount FROM payments WINDOW w_ordered AS (PARTITION BY method ORDER BY amount, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING)) SELECT id, order_id, method, amount, paid_at, amount_avg_6_prior, order_id_sum_amount, CASE WHEN method RLIKE '^(promptpay|paypal)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS method_zone FROM scored ORDER BY order_id_sum_amount NULLS FIRST
